package com.star.Ba.Agricole;

public class ParcellePrint {
	private String NomParcelle, Superficie, NatureRecoltes, PrixUnitaire, Localisation, Rendement,variete,nbrPieds;
	
	public ParcellePrint() {
		// TODO Auto-generated constructor stub
	}

	public String getNomParcelle() {
		return NomParcelle;
	}

	public void setNomParcelle(String nomParcelle) {
		NomParcelle = nomParcelle;
	}

	public String getSuperficie() {
		return Superficie;
	}

	public void setSuperficie(String superficie) {
		Superficie = superficie;
	}

	public String getNatureRecoltes() {
		return NatureRecoltes;
	}

	public void setNatureRecoltes(String natureRecoltes) {
		NatureRecoltes = natureRecoltes;
	}

	public String getPrixUnitaire() {
		return PrixUnitaire;
	}

	public void setPrixUnitaire(String prixUnitaire) {
		PrixUnitaire = prixUnitaire;
	}

	public String getLocalisation() {
		return Localisation;
	}

	public void setLocalisation(String localisation) {
		Localisation = localisation;
	}

	public String getRendement() {
		return Rendement;
	}

	public void setRendement(String rendement) {
		Rendement = rendement;
	}

	public String getVariete() {
		return variete;
	}

	public void setVariete(String variete) {
		this.variete = variete;
	}

	public String getNbrPieds() {
		return nbrPieds;
	}

	public void setNbrPieds(String nbrPieds) {
		this.nbrPieds = nbrPieds;
	}
	
	
	
	
}
